// Verus program: splitlines
// Transforms a non-empty Vec<String> into a Vec<Vec<String>> with:
// (1) same outer length as input
// (2) each inner Vec<String> is non-empty
//
// The `keepends` flag may affect the concrete splitting policy, but the only
// required guarantees are the two properties above.

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn splitlines(a: Vec<String>, keepends: bool) -> (out: Vec<Vec<String>>)
    requires
        a.len() > 0,
    ensures
        out.len() == a.len(),
        forall|i: int| 0 <= i < out.len() ==> out[i].len() > 0,
{
    // Simple, specification-friendly implementation:
    // for each input string, produce a singleton list containing that string.
    // This trivially preserves outer length and guarantees each inner list is non-empty.
    let mut out: Vec<Vec<String>> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            out.len() == i,
            forall|j: int| 0 <= j < out.len() ==> out[j].len() > 0,
    {
        // Make a non-empty inner vector
        let mut inner: Vec<String> = Vec::new();
        inner.push(a[i].clone());

        // keepends could influence a more complex policy; unused here by design.
        let _ = keepends;

        out.push(inner);
        i += 1;
    }

    out
}

} // verus!